SELECT CASE WHEN orders.discount >= 0.39 THEN 'high' WHEN orders.discount >= 0.16 THEN 'mid' ELSE 'low' END AS discount_bucket, ROUND(AVG(shipments.cost), 2) AS avg_cost FROM shipments INNER JOIN orders ON shipments.order_id = orders.id INNER JOIN customers ON orders.customer_id = customers.id GROUP BY CASE WHEN orders.discount >= 0.39 THEN 'high' WHEN orders.discount >= 0.16 THEN 'mid' ELSE 'low' END HAVING ROUND(AVG(shipments.cost), 2) > 77
